@namespace sv_52692d2782ab49c584d8bad14d8cbfdd.Components.Pages.Settings

<nav class="settings-sidebar" role="tablist" aria-label="Settings sections">
    @foreach (var section in Sections)
    {
        var isActive = section == ActiveSection;
        <button class="sidebar-item @(isActive ? "active" : "")"
                role="tab"
                aria-selected="@isActive"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "Profile";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 1rem;
    min-width: 200px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    height: 100%;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: none;
    border-radius: 0.5rem;
    background: transparent;
    color: #495057;
    font-size: 0.95rem;
    cursor: pointer;
    text-align: left;
    transition: background-color 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

