@namespace sv_52692d2782ab49c584d8bad14d8cbfdd.Components.Pages.Settings

<div class="modal-backdrop" @onclick="OnCancel.InvokeAsync">
    <div class="modal-dialog" @onclick:stopPropagation="true">
        <div class="modal-content">
            <div class="modal-header">
                <h5 class="modal-title">Revoke Session</h5>
                <button type="button" class="btn-close" @onclick="OnCancel.InvokeAsync"></button>
            </div>
            <div class="modal-body">
                <p>Are you sure you want to revoke the session on <strong>@Device</strong> from <strong>@Location</strong>?</p>
                <p class="text-muted">This will sign the device out immediately.</p>
            </div>
            <div class="modal-footer">
                <button class="btn btn-outline-secondary" @onclick="OnCancel.InvokeAsync">Cancel</button>
                <button class="btn btn-danger" @onclick="OnConfirm.InvokeAsync">Revoke Session</button>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Device { get; set; } = "";
    [Parameter, EditorRequired] public string Location { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnConfirm { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
}

.modal-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.modal-dialog {
    background: #fff;
    border-radius: 0.5rem;
    max-width: 450px;
    width: 90%;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.modal-content {
    display: flex;
    flex-direction: column;
}

.modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    border-bottom: 1px solid #dee2e6;
}

.modal-header .modal-title {
    margin: 0;
}

.modal-body {
    padding: 1.25rem;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 1rem 1.25rem;
    border-top: 1px solid #dee2e6;
}

@namespace sv_52692d2782ab49c584d8bad14d8cbfdd.Components.Pages.Settings
@using sv_52692d2782ab49c584d8bad14d8cbfdd.Services
@inject ISettingsService SettingsService

<div class="security-section">
    @if (_loading)
    {
        <p class="text-muted">Loading security settings…</p>
    }
    else
    {
        <!-- Change Password -->
        <div class="settings-card">
            <button class="card-header-btn" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <h5>Change Password</h5>
                <span class="expand-icon">@(_passwordExpanded ? "▲" : "▼")</span>
            </button>

            @if (_passwordExpanded)
            {
                <div class="card-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" class="form-control" @bind="_confirmPassword" />
                    </div>

                    @if (_passwordError is not null)
                    {
                        <div class="alert alert-danger mt-2" role="alert">@_passwordError</div>
                    }

                    @if (_passwordSuccess)
                    {
                        <div class="alert alert-success mt-2" role="alert">Password updated successfully!</div>
                    }

                    <button class="btn btn-primary mt-2" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating…" : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="settings-card">
            <div class="twofa-row">
                <div>
                    <h5>Two-Factor Authentication</h5>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="settings-card">
            <h5>Active Sessions</h5>
            @if (_sessions.Count == 0)
            {
                <p class="text-muted">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-striped">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _sessions)
                            {
                                var isCurrentSession = session == _sessions[0];
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                        else
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>

        @if (_sessionToRevoke is not null)
        {
            <RevokeSessionDialog Device="@_sessionToRevoke.Device"
                                 Location="@_sessionToRevoke.Location"
                                 OnConfirm="RevokeConfirmedAsync"
                                 OnCancel="() => _sessionToRevoke = null" />
        }

        @if (_revokeError is not null)
        {
            <div class="alert alert-danger mt-3" role="alert">@_revokeError</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = [];

    // Password change
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordError;
    private bool _passwordSuccess;

    // Session revocation
    private ActiveSession? _sessionToRevoke;
    private string? _revokeError;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = $"Failed to change password: {ex.Message}";
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _revokeError = null;
    }

    private async Task RevokeConfirmedAsync()
    {
        if (_sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            _revokeError = $"Failed to revoke session: {ex.Message}";
            _sessionToRevoke = null;
        }
    }
}

