@namespace sv_52692d2782ab49c584d8bad14d8cbfdd.Components.Pages.Settings
@using sv_52692d2782ab49c584d8bad14d8cbfdd.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        <div class="settings-row">
            <h5>Theme</h5>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-option">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="settings-row">
            <h5>Font Size</h5>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-option">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="settings-row">
            <h5>Language</h5>
            <select class="form-select" @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <div class="settings-row">
            <h5>Compact Mode</h5>
            <label class="toggle-row">
                <input type="checkbox" class="form-check-input" @bind="_compactMode" />
                <span>Reduce spacing and use smaller elements</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="settings-row">
            <h5>Preview</h5>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">Appearance settings saved!</div>
        }

        @if (_errorMessage is not null)
        {
            <div class="alert alert-danger mt-3" role="alert">@_errorMessage</div>
        }
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = _theme.ToLowerInvariant();
        var size = _fontSize.ToLowerInvariant();
        var compact = _compactMode ? "compact" : "";
        return $"theme-{theme} font-{size} {compact}".Trim();
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save appearance: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

.appearance-section {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    max-width: 600px;
}

.settings-row h5 {
    margin-bottom: 0.5rem;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

/* Live preview area */
.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    transition: all 0.2s;
}

.preview-header {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: #fff;
    border-radius: 0.375rem;
    cursor: default;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-button {
    background: #3b82f6;
    border-color: #3b82f6;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font size variants */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.6rem;
    line-height: 1.3;
}

.preview-area.compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-area.compact .preview-button {
    padding: 0.2rem 0.6rem;
    font-size: 0.85em;
}

