toolArgs.file_text:
.appearance-section {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    max-width: 600px;
}

.settings-row h5 {
    margin-bottom: 0.5rem;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

/* Live preview area */
.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    transition: all 0.2s;
}

.preview-header {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-button {
    padding: 0.4rem 1rem;
    border: 1px solid #0d6efd;
    background: #0d6efd;
    color: #fff;
    border-radius: 0.375rem;
    cursor: default;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-button {
    background: #3b82f6;
    border-color: #3b82f6;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font size variants */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.6rem;
    line-height: 1.3;
}

.preview-area.compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-area.compact .preview-button {
    padding: 0.2rem 0.6rem;
    font-size: 0.85em;
}

